<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { auth } from '@/firebase'
import { changeListingStatus, formatMoney, getListing } from '@/services/marketplace'
import { contactSeller } from '@/services/inquiries'
const route=useRoute(),router=useRouter(),listing=ref(null),loading=ref(true),busy=ref(false),error=ref(''),text=ref(''),confirmation=ref(''),failed=ref(false)
const own=computed(()=>listing.value?.sellerId===auth.currentUser?.uid)
async function load(){loading.value=true;error.value='';try{listing.value=await getListing(route.params.id)}catch(cause){error.value=cause.message}finally{loading.value=false}}
async function setStatus(){busy.value=true;error.value='';try{await changeListingStatus(listing.value.id,confirmation.value);confirmation.value='';await load()}catch(cause){error.value=cause.message}finally{busy.value=false}}
async function contact(){if(!auth.currentUser)return router.push({name:'login',query:{redirect:route.fullPath}});busy.value=true;error.value='';try{const id=await contactSeller(listing.value,text.value);await router.push({name:'messages',query:{thread:id}})}catch(cause){error.value=cause.message}finally{busy.value=false}}
watch(()=>route.params.id,load)
onMounted(load)
</script>
<template>
  <main class="collection-page mx-auto max-w-[1440px] px-6 py-10 sm:px-8 lg:px-16"><RouterLink to="/marketplace" class="text-sm text-apricot">← Back to marketplace</RouterLink><p v-if="error" role="alert" class="mt-5 text-red-200">{{ error }}</p><p v-if="loading" role="status" class="mt-8">Loading listing…</p>
    <template v-else-if="listing"><header class="my-6"><p class="text-xs uppercase text-[#b4becc]">Marketplace / Listing · {{ listing.status }}</p><h1 class="display-font mt-2 text-4xl font-bold">{{ listing.name }}</h1><p class="mt-3 text-[#b4becc]">{{ listing.setName }} · {{ listing.localId }} · {{ listing.variant }} · {{ listing.language }} · {{ listing.condition }}</p></header>
      <div class="grid items-start gap-8 lg:grid-cols-[1.5fr_1fr]"><section class="market-panel"><h2 class="display-font text-xl font-bold">Card and photos</h2><img v-if="listing.image&&!failed" :src="listing.image" :alt="listing.name" class="mx-auto mt-5 h-80 w-full object-contain" @error="failed=true" /><p class="mt-3 text-center text-xs text-[#b4becc]">Catalogue image</p><div v-if="listing.photos.length" class="mt-6 grid gap-4 sm:grid-cols-2"><a v-for="(photo,index) in listing.photos" :key="photo.path" :href="photo.url" target="_blank" rel="noopener noreferrer"><img :src="photo.url" :alt="`Seller photo ${index+1} of ${listing.name}`" class="h-72 w-full rounded-xl object-contain" /></a></div><h2 class="display-font mt-6 text-xl font-bold">Description</h2><p class="mt-3 whitespace-pre-wrap break-words text-sm leading-6 text-[#b4becc]">{{ listing.description||'No additional description provided.' }}</p></section>
        <section class="market-panel"><h2 class="display-font text-xl font-bold">Seller: {{ listing.sellerName }}</h2><p class="mt-5 text-3xl font-bold">{{ formatMoney(listing.priceCents) }} <span class="text-sm font-normal">per card</span></p><p class="mt-3 text-sm">Quantity: {{ listing.quantity }}</p><p class="mt-3 text-sm">{{ listing.delivery==='pickup'?'Local pickup':`Tracked shipping: ${formatMoney(listing.shippingCents)}` }}</p><p class="mt-5 text-xl font-bold text-apricot">Total: {{ formatMoney(listing.priceCents*listing.quantity+listing.shippingCents) }}</p><p class="mt-2 text-xs text-[#b4becc]">{{ listing.delivery === 'pickup' ? 'All listed cards for local pickup.' : 'All listed cards plus one shipping charge.' }} Arrange payment and delivery directly with the seller.</p>
          <template v-if="own&&listing.status==='active'"><RouterLink :to="`/marketplace/${listing.id}/edit`" class="market-button mt-6 inline-block">Edit listing</RouterLink><div class="mt-4 flex flex-wrap gap-4"><button :disabled="busy" class="text-sm text-mint underline" @click="confirmation='sold'">Mark as sold</button><button :disabled="busy" class="text-sm text-apricot underline" @click="confirmation='withdrawn'">Withdraw listing</button></div><div v-if="confirmation" class="mt-5 rounded-xl bg-ink p-4"><p class="text-sm">{{ confirmation==='sold'?`Mark all ${listing.quantity} cards as sold? This will remove that quantity from your collection.`:'Withdraw this listing from the marketplace?' }}</p><div class="mt-3 flex gap-4"><button :disabled="busy" class="market-button" @click="setStatus">{{ busy?'Saving…':'Confirm' }}</button><button :disabled="busy" @click="confirmation=''">Cancel</button></div></div></template>
          <form v-else-if="!own&&listing.status==='active'" class="mt-6" @submit.prevent="contact"><label class="text-sm">Contact seller<textarea v-model="text" maxlength="2000" :required="!!auth.currentUser" placeholder="Hi, is this card still available?" class="market-field mt-2 min-h-28"></textarea></label><button :disabled="busy" class="market-button mt-3">{{ busy?'Sending…':auth.currentUser?'Send message':'Sign in to contact seller' }}</button></form>
        </section>
      </div>
    </template>
  </main>
</template>
